contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address a) public payable {
        address ownerBefore = c.owner(); if (__ESBMC_reverted()) return;

        bool reverted;
        c.setOwner(a); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

        address ownerAfter = c.owner(); if (__ESBMC_reverted()) return;

        assert(
            reverted
                ? (ownerAfter == ownerBefore)
                : (ownerAfter == a)
        );
    }

    receive() external payable {}
}

